"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";

type Currency = { id: string; code: string };
type Provider = { id: string; name: string; websiteUrl?: string | null };
type Account = { id: string; name: string; accountType: string; provider: Provider; currency: Currency; accountNumberMasked?: string | null; note?: string | null; isActive?: boolean; cashAccount?: { id: string; balance: string | number } | null };
type Asset = { id: string; symbol?: string | null; name: string; assetType: string; unitName: string; currency: Currency };
type Holding = { id: string; quantity: string | number; costBasis: string | number; currentPrice?: string | number | null; marketValue: string | number; gain: string | number; returnPct: string | number; asset: Asset; account: Account };
type Cash = { id: string; balance: string | number; account: Account };
type Sale = { id: string; date: string; quantity: string | number; price: string | number; proceeds: string | number; realized: string | number };
type LotRow = { id: string; lotId: string; transactionDate: string; asset: Asset; quantity: string | number; soldQuantity: string | number; remainingQuantity: string | number; unitPrice: string | number; totalCost: string | number; minimumSellPrice: string | number; currentPrice: string | number | null; priceAsOf: string | null; currentValue: string | number; unrealizedGainLoss: string | number; sales: Sale[] };
type Ledger = { account: Account; rows: LotRow[]; summary: { openLots: number; openQuantity: string | number; realizedGainLoss: string | number } };
type Overview = { currencies: Currency[]; providers: Provider[]; accounts: Account[]; assets: Asset[]; holdings: Holding[]; cashAccounts: Cash[]; summary: { totalValue: string | number; totalCash: string | number; totalInvestmentValue: string | number; unrealized: string | number; returnPct: string | number } };
type RdnHistoryRow = { id: string; date: string; description: string; debit: string | number; credit: string | number; balance: string | number; movementType: string };
type AssetSummary = { asset: Asset; quantity: number; cost: number; avgCost: number; currentPrice: number | null; marketValue: number; sellFee: number; netValue: number; pnl: number; minSell: number; rows: LotRow[] };
type Trade = { type: "BUY" | "SELL"; assetId: string; assetQuery: string; quantity: string; unitPrice: string; tax: string; other: string; date: string; sourceLotId: string; fundingCashAccountId: string };
type AccountForm = { providerName: string; websiteUrl: string; rdnBankName: string; rdnAccountNumber: string; buyFeePct: string; sellFeePct: string; currencyId: string };

const input = "w-full rounded-xl border border-white/10 bg-[#080f17] px-3 py-2.5 text-sm text-white outline-none placeholder:text-slate-600";
const select = `${input} text-slate-300`;
const card = "rounded-2xl border border-white/10 bg-[#0d151e] p-5";
const today = () => new Date().toISOString().slice(0, 10);
const numberFormat = (value: string | number | null | undefined, digits = 2) => { const n = Number(value ?? 0); return Number.isFinite(n) ? new Intl.NumberFormat("id-ID", { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(n) : "0"; };
const currencyPrefix = (code: string) => ({ IDR: "Rp", USD: "US$", SGD: "S$", MYR: "RM", JPY: "¥", EUR: "€", GBP: "£" } as Record<string, string>)[code] ?? code;
const money = (value: string | number | null | undefined, code = "IDR") => `${currencyPrefix(code)}${numberFormat(value)}`;
const feeInfo = (a: Account) => { try { const parsed = a.note ? JSON.parse(a.note) as Record<string, unknown> : {}; return { buyFeePct: Number(parsed.buyFeePct ?? 0) || 0, sellFeePct: Number(parsed.sellFeePct ?? 0) || 0, rdnBankName: String(parsed.rdnBankName ?? ""), rdnAccountNumber: String(parsed.rdnAccountNumber ?? "") }; } catch { return { buyFeePct: 0, sellFeePct: 0, rdnBankName: "", rdnAccountNumber: "" }; } };
const stockUnits = (asset?: Asset) => asset?.assetType === "STOCK" ? 100 : 1;
const assetLabel = (asset: Asset) => asset.symbol ? `${asset.symbol} · ${asset.name}` : asset.name;

async function getOverview(): Promise<Overview> { const r = await fetch("/api/investments", { cache: "no-store" }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Unable to load investments."); return j; }
async function postV2(body: Record<string, unknown>) { const r = await fetch("/api/investments/v2", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Investment operation failed."); return j; }
async function postV4(body: Record<string, unknown>) { const r = await fetch("/api/investments/v4", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Investment operation failed."); return j; }

function AssetPicker({ assets, value, selectedId, onQueryChange, onSelect }: { assets: Asset[]; value: string; selectedId: string; onQueryChange: (value: string) => void; onSelect: (asset: Asset) => void }) {
  const [open, setOpen] = useState(false);
  const q = value.trim().toLowerCase();
  const filtered = useMemo(() => assets.filter(a => !q || assetLabel(a).toLowerCase().includes(q) || String(a.symbol ?? "").toLowerCase() === q || a.name.toLowerCase().includes(q)), [assets, q]);
  return <div className="relative">
    <input className={`${input} ${selectedId ? "border-emerald-400/40" : ""}`} placeholder="Asset / Stock (type to search)" value={value} autoComplete="off" onFocus={() => setOpen(true)} onChange={e => { const next = e.target.value; onQueryChange(next); setOpen(true); const exact = assets.find(a => String(a.symbol ?? "").toLowerCase() === next.trim().toLowerCase() || assetLabel(a).toLowerCase() === next.trim().toLowerCase()); if (exact) onSelect(exact); }} onBlur={() => window.setTimeout(() => setOpen(false), 120)} />
    {open && <div className="absolute z-[80] mt-1 max-h-64 w-full overflow-y-auto rounded-xl border border-white/10 bg-[#0b121a] p-1 shadow-2xl">
      {filtered.length ? filtered.map(a => <button key={a.id} type="button" onMouseDown={e => e.preventDefault()} onClick={() => { onSelect(a); setOpen(false); }} className="flex w-full items-center justify-between rounded-lg px-3 py-2 text-left hover:bg-white/[.05]"><span><span className="block text-sm font-semibold text-white">{a.symbol || a.name}</span><span className="block text-[10px] text-slate-500">{a.name}</span></span><span className="text-[9px] uppercase text-slate-600">{a.assetType}</span></button>) : <div className="px-3 py-4 text-xs text-slate-600">Asset tidak ditemukan. Untuk BUY, asset baru akan dibuat otomatis.</div>}
    </div>}
  </div>;
}

export default function InvestmentDashboardV4() {
  const [data, setData] = useState<Overview | null>(null);
  const [screen, setScreen] = useState<"overview" | "transactions" | "accounts">("overview");
  const [accountId, setAccountId] = useState("");
  const [ledger, setLedger] = useState<Ledger | null>(null);
  const [historyAccountId, setHistoryAccountId] = useState("");
  const [historyRows, setHistoryRows] = useState<RdnHistoryRow[]>([]);
  const [historyOpen, setHistoryOpen] = useState(false);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const [showTrade, setShowTrade] = useState(false);
  const [showSellAll, setShowSellAll] = useState(false);
  const [sellAllAssetId, setSellAllAssetId] = useState("");
  const [sellAllPrice, setSellAllPrice] = useState("");
  const [editing, setEditing] = useState<Account | null>(null);
  const [accountForm, setAccountForm] = useState<AccountForm>({ providerName: "", websiteUrl: "", rdnBankName: "", rdnAccountNumber: "", buyFeePct: "", sellFeePct: "", currencyId: "" });
  const [cashForm, setCashForm] = useState({ cashAccountId: "", balance: "", date: "" });
  const [trade, setTrade] = useState<Trade>({ type: "BUY", assetId: "", assetQuery: "", quantity: "", unitPrice: "", tax: "0", other: "0", date: "", sourceLotId: "", fundingCashAccountId: "" });
  const [importing, setImporting] = useState(false);

  const reload = async () => setData(await getOverview());
  const loadLedger = async (id: string) => { const r = await fetch(`/api/investments/v2?accountId=${encodeURIComponent(id)}`, { cache: "no-store" }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Unable to load transactions."); setLedger(j); };
  const loadHistory = async (id: string) => { if (!id) { setHistoryRows([]); return; } setHistoryLoading(true); try { const r = await fetch(`/api/investments/cash-transfer?cashAccountId=${encodeURIComponent(id)}`, { cache: "no-store" }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Unable to load RDN history."); setHistoryRows(j.rows ?? []); } finally { setHistoryLoading(false); } };

  useEffect(() => { setTrade(x => x.date ? x : { ...x, date: today() }); setCashForm(x => x.date ? x : { ...x, date: today() }); reload().catch(e => setMessage(e instanceof Error ? e.message : "Unable to load investments.")); }, []);
  useEffect(() => { if (accountId) loadLedger(accountId).catch(e => setMessage(e instanceof Error ? e.message : "Unable to load transactions.")); }, [accountId]);
  useEffect(() => { if (historyOpen && historyAccountId) loadHistory(historyAccountId).catch(e => setMessage(e instanceof Error ? e.message : "Unable to load RDN history.")); }, [historyOpen, historyAccountId]);

  const accounts = data?.accounts ?? [];
  const currencies = data?.currencies ?? [];
  const assets = data?.assets ?? [];
  const holdings = data?.holdings ?? [];
  const cashAccounts = data?.cashAccounts ?? [];
  const selected = accounts.find(a => a.id === accountId);
  const selectedCash = cashAccounts.find(c => c.id === selected?.cashAccount?.id);
  const transactionAssets = useMemo(() => { const seen = new Set<string>(); const out: Asset[] = []; for (const row of ledger?.rows ?? []) if (!seen.has(row.asset.id)) { seen.add(row.asset.id); out.push(row.asset); } return out; }, [ledger]);
  const pickerAssets = useMemo(() => { const seen = new Set<string>(); return [...transactionAssets, ...assets].filter(a => !seen.has(a.id) && seen.add(a.id)); }, [transactionAssets, assets]);
  const selectedAsset = pickerAssets.find(a => a.id === trade.assetId) ?? pickerAssets.find(a => assetLabel(a).toLowerCase() === trade.assetQuery.trim().toLowerCase());
  const fee = selected ? feeInfo(selected) : { buyFeePct: 0, sellFeePct: 0, rdnBankName: "", rdnAccountNumber: "" };
  const compatibleCash = cashAccounts.filter(c => selected && c.account.id === selected.id && c.account.provider.id === selected.provider.id && c.account.currency.id === selected.currency.id);
  const sellLot = trade.type === "SELL" && trade.sourceLotId ? ledger?.rows.find(r => r.lotId === trade.sourceLotId) : undefined;
  const sellUnits = trade.type === "SELL" && selectedAsset ? Number(trade.quantity || 0) * stockUnits(selectedAsset) : 0;
  const sellRemaining = sellLot ? Number(sellLot.remainingQuantity) : 0;
  const sellValid = trade.type !== "SELL" || !trade.quantity || sellUnits <= sellRemaining;

  const assetSummaries = useMemo<AssetSummary[]>(() => {
    if (!ledger || !selected) return [];
    const sellFeePct = feeInfo(selected).sellFeePct;
    const groups = new Map<string, LotRow[]>();
    for (const row of ledger.rows) {
      const remaining = Number(row.remainingQuantity);
      if (remaining <= 0) continue;
      const list = groups.get(row.asset.id) ?? [];
      list.push(row);
      groups.set(row.asset.id, list);
    }
    return [...groups.values()].map(rows => {
      const asset = rows[0].asset;
      const units = stockUnits(asset);
      const quantity = rows.reduce((s, r) => s + Number(r.remainingQuantity), 0);
      const cost = rows.reduce((s, r) => s + Number(r.totalCost) * (Number(r.remainingQuantity) / Math.max(Number(r.quantity), 1)), 0);
      const avgCost = quantity > 0 ? cost / quantity : 0;
      const currentPrice = rows.find(r => r.currentPrice != null)?.currentPrice == null ? null : Number(rows.find(r => r.currentPrice != null)?.currentPrice);
      const marketValue = currentPrice == null ? 0 : quantity * currentPrice;
      const sellFee = marketValue * sellFeePct / 100;
      const netValue = marketValue - sellFee;
      const pnl = netValue - cost;
      const minSell = quantity > 0 && sellFeePct < 100 ? (cost / quantity) / (1 - sellFeePct / 100) : 0;
      return { asset, quantity, cost, avgCost, currentPrice, marketValue, sellFee, netValue, pnl, minSell, rows };
    }).sort((a, b) => (b.marketValue - a.marketValue) || a.asset.name.localeCompare(b.asset.name));
  }, [ledger, selected]);

  const openRows = useMemo(() => [...(ledger?.rows ?? [])].filter(r => Number(r.remainingQuantity) > 0).sort((a, b) => new Date(b.transactionDate).getTime() - new Date(a.transactionDate).getTime()), [ledger]);
  const closedSales = useMemo(() => (ledger?.rows ?? []).flatMap(r => r.sales.map(s => ({ lot: r, sale: s }))).sort((a, b) => new Date(b.sale.date).getTime() - new Date(a.sale.date).getTime()), [ledger]);
  const sellAllAsset = assetSummaries.find(a => a.asset.id === sellAllAssetId);
  const sellAllPreview = sellAllAsset && sellAllPrice ? (() => { const price = Number(sellAllPrice); const sellFeePct = feeInfo(selected!).sellFeePct; const rows = sellAllAsset.rows.map(row => { const qty = Number(row.remainingQuantity); const gross = qty * price; const sellFee = gross * sellFeePct / 100; const cost = Number(row.totalCost) * (qty / Math.max(Number(row.quantity), 1)); const net = gross - sellFee; return { row, qty, gross, sellFee, net, cost, pnl: net - cost }; }); return { rows, totalGross: rows.reduce((s, r) => s + r.gross, 0), totalFee: rows.reduce((s, r) => s + r.sellFee, 0), totalNet: rows.reduce((s, r) => s + r.net, 0), totalCost: rows.reduce((s, r) => s + r.cost, 0), pnl: rows.reduce((s, r) => s + r.pnl, 0) }; })() : null;

  const run = async (body: Record<string, unknown>, success: string, route = "v2") => { setBusy(true); setMessage(""); try { if (route === "v4") await postV4(body); else await postV2(body); await reload(); if (accountId) await loadLedger(accountId); setMessage(success); return true; } catch (e) { setMessage(e instanceof Error ? e.message : "Operation failed."); return false; } finally { setBusy(false); } };

  const chooseAccount = (id: string, destination: "transactions" | "accounts" = "accounts") => { setAccountId(id); setScreen(destination); setHistoryAccountId(accounts.find(a => a.id === id)?.cashAccount?.id ?? ""); setLedger(null); };
  const openAccountEditor = (account?: Account) => { setEditing(account ?? null); if (account) { const f = feeInfo(account); setAccountForm({ providerName: account.provider.name, websiteUrl: account.provider.websiteUrl || "", rdnBankName: f.rdnBankName, rdnAccountNumber: f.rdnAccountNumber, buyFeePct: String(f.buyFeePct), sellFeePct: String(f.sellFeePct), currencyId: account.currency.id }); } else setAccountForm({ providerName: "", websiteUrl: "", rdnBankName: "", rdnAccountNumber: "", buyFeePct: "", sellFeePct: "", currencyId: currencies[0]?.id || "" }); };
  const openTrade = (type: "BUY" | "SELL", row?: LotRow) => { setTrade({ type, assetId: row?.asset.id ?? "", assetQuery: row ? assetLabel(row.asset) : "", quantity: "", unitPrice: row?.currentPrice ? String(row.currentPrice) : "", tax: "0", other: "0", date: today(), sourceLotId: row?.lotId ?? "", fundingCashAccountId: compatibleCash[0]?.id ?? selected?.cashAccount?.id ?? "" }); setShowTrade(true); };
  const chooseAsset = (asset: Asset) => setTrade(x => ({ ...x, assetId: asset.id, assetQuery: assetLabel(asset), sourceLotId: x.type === "SELL" ? x.sourceLotId : "" }));

  async function submitTrade(e: FormEvent) {
    e.preventDefault(); if (!selected) return;
    let effectiveAsset = selectedAsset;
    if (!effectiveAsset && trade.type === "BUY") { const symbol = trade.assetQuery.trim().toUpperCase(); if (!symbol) { setMessage("Enter an asset / stock first."); return; } try { effectiveAsset = await postV2({ action: "asset.resolve", accountId: selected.id, symbol, name: symbol, currencyId: selected.currency.id, assetType: "STOCK", unitName: "share" }); setData(prev => prev ? { ...prev, assets: [...prev.assets.filter(a => a.id !== effectiveAsset?.id), effectiveAsset as Asset] } : prev); } catch (e) { setMessage(e instanceof Error ? e.message : "Unable to resolve asset."); return; } }
    if (!effectiveAsset || !trade.quantity || !trade.unitPrice || !trade.fundingCashAccountId) { setMessage("Lengkapi asset, quantity, harga dan RDN."); return; }
    if (trade.type === "SELL" && (!trade.sourceLotId || !sellValid)) { setMessage("Jumlah jual melebihi remaining lot atau lot belum dipilih."); return; }
    const units = stockUnits(effectiveAsset); const qty = Number(trade.quantity) * units; const gross = qty * Number(trade.unitPrice); const feePct = trade.type === "BUY" ? fee.buyFeePct : fee.sellFeePct; const autoFee = gross * feePct / 100;
    const ok = await run({ action: "transaction.create", accountId: selected.id, assetId: effectiveAsset.id, transactionType: trade.type, transactionDate: new Date(trade.date).toISOString(), quantity: qty, unitPrice: Number(trade.unitPrice), feeAmount: autoFee, taxAmount: Number(trade.tax || 0), otherCharges: Number(trade.other || 0), fundingCashAccountId: trade.fundingCashAccountId, sourceLotId: trade.sourceLotId || undefined }, "Transaction saved.");
    if (ok) setShowTrade(false);
  }

  async function saveAccount(e: FormEvent) { e.preventDefault(); const payload = { ...accountForm, buyFeePct: Number(accountForm.buyFeePct || 0), sellFeePct: Number(accountForm.sellFeePct || 0) }; const ok = await run(editing ? { action: "account.update", accountId: editing.id, ...payload } : { action: "account.create", ...payload }, editing ? "Account updated." : "Account created.", "v4"); if (ok) setEditing(null); }
  async function accountAction(action: "account.close" | "account.delete", account: Account) { const label = action === "account.close" ? "tutup" : "hapus"; if (!window.confirm(`Yakin ingin ${label} account ${account.provider.name}?`)) return; await run({ action, accountId: account.id }, action === "account.close" ? "Account closed." : "Account deleted.", "v4"); }
  async function saveCash(e: FormEvent) { e.preventDefault(); if (!cashForm.cashAccountId) return; const ok = await run({ action: "cash.setBalance", cashAccountId: cashForm.cashAccountId, balance: Number(cashForm.balance), date: new Date(cashForm.date).toISOString() }, "RDN balance updated."); if (ok) setHistoryAccountId(cashForm.cashAccountId); }
  async function withdrawToWallet(cashAccountId: string, amount: string, walletId: string) { const value = Number(amount); if (!cashAccountId || !walletId || !value) return; setBusy(true); setMessage(""); try { const r = await fetch("/api/investments/cash-transfer", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ direction: "WITHDRAW", cashAccountId, walletId, amount: value, date: new Date().toISOString() }) }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Withdrawal failed."); await reload(); if (accountId) await loadLedger(accountId); setHistoryAccountId(cashAccountId); setHistoryOpen(true); await loadHistory(cashAccountId); setMessage(`Dana ${money(value, selected?.currency.code)} berhasil dipindahkan ke Wallet.`); } catch (e) { setMessage(e instanceof Error ? e.message : "Withdrawal failed."); } finally { setBusy(false); } }
  async function importExcel(file: File) { if (!selected) return; setImporting(true); try { const form = new FormData(); form.append("action", "import.excel"); form.append("accountId", selected.id); form.append("file", file); const r = await fetch("/api/investments/v2", { method: "POST", body: form }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Import failed."); await reload(); await loadLedger(selected.id); setMessage(`Imported ${j.imported} rows. Skipped ${j.skipped}.`); } catch (e) { setMessage(e instanceof Error ? e.message : "Import failed."); } finally { setImporting(false); } }
  async function sellAll() { if (!selected || !sellAllAsset || !sellAllPrice || !selected.cashAccount?.id) return; const ok = await run({ action: "transaction.sellAll", accountId: selected.id, assetId: sellAllAsset.asset.id, transactionDate: new Date(today()).toISOString(), unitPrice: Number(sellAllPrice), fundingCashAccountId: selected.cashAccount.id }, "Sell All completed.", "v4"); if (ok) { setShowSellAll(false); setSellAllAssetId(""); setSellAllPrice(""); } }

  const renderRdnHistory = (cashId: string) => { const cash = cashAccounts.find(c => c.id === cashId); if (!cash || !historyOpen || historyAccountId !== cashId) return null; return <div className="mt-4 overflow-hidden rounded-2xl border border-white/10 bg-[#0d151e]"><div className="flex items-center justify-between border-b border-white/5 px-5 py-4"><div><p className="text-[10px] uppercase tracking-widest text-slate-500">RDN history</p><h3 className="mt-1 font-semibold text-white">Transaction History</h3><p className="mt-1 text-xs text-slate-600">{cash.account.provider.name} · {cash.account.name}</p></div><button type="button" onClick={() => setHistoryOpen(false)} className="text-slate-500 hover:text-white">✕</button></div>{historyLoading ? <div className="p-8 text-center text-xs text-slate-600">Loading…</div> : !historyRows.length ? <div className="p-8 text-center text-xs text-slate-600">Belum ada transaksi pada RDN ini.</div> : <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-xs"><thead className="border-b border-white/5 text-[10px] uppercase tracking-wider text-slate-600"><tr><th className="px-5 py-3">Date</th><th>Type</th><th>Description</th><th className="text-right">Debit</th><th className="text-right">Credit</th><th className="px-5 text-right">Balance</th></tr></thead><tbody className="divide-y divide-white/5">{historyRows.map(row => <tr key={row.id}><td className="px-5 py-3 text-slate-400">{new Date(row.date).toLocaleDateString("id-ID")}</td><td className="text-slate-500">{row.movementType}</td><td className="text-slate-300">{row.description}</td><td className="text-right text-red-300">{Number(row.debit) ? money(row.debit, cash.account.currency.code) : "—"}</td><td className="text-right text-emerald-300">{Number(row.credit) ? money(row.credit, cash.account.currency.code) : "—"}</td><td className="px-5 text-right font-semibold text-white">{money(row.balance, cash.account.currency.code)}</td></tr>)}</tbody></table></div>}</div>; };

  if (!data) return <div className="mx-auto w-full max-w-[1450px] px-5 py-8 text-sm text-slate-400">Loading Investments…</div>;

  return <div className="mx-auto w-full min-w-0 max-w-[1450px] px-5 py-8 lg:px-8">
    <header className="mb-6 flex w-full flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><p className="text-[10px] font-semibold uppercase tracking-[.18em] text-emerald-400">Portfolio</p><h1 className="mt-1 text-3xl font-bold text-white">Investments</h1><p className="mt-2 text-sm text-slate-500">Accounts, holdings, transactions, RDN cash and performance.</p></div><nav className="flex shrink-0 flex-wrap gap-1 rounded-xl border border-white/10 bg-[#0b121a] p-1">{([["overview","Overview"],["transactions","Transactions"],["accounts","Accounts"]] as const).map(([k,l]) => <button key={k} onClick={() => setScreen(k)} className={`rounded-lg px-4 py-2 text-xs font-bold uppercase tracking-wide ${screen === k ? "bg-white/[.09] text-white" : "text-slate-500 hover:text-slate-300"}`}>{l}</button>)}</nav></header>
    {message && <div className={`mb-4 rounded-xl border px-4 py-3 text-xs ${/error|failed|insufficient|cannot|must|valid|melebihi|tidak/i.test(message) ? "border-red-400/20 bg-red-400/[.05] text-red-300" : "border-emerald-400/20 bg-emerald-400/[.05] text-emerald-300"}`}>{message}</div>}

    {screen === "overview" && <div className="space-y-5"><div className="grid gap-3 md:grid-cols-4">{[["Total Investment",data.summary.totalInvestmentValue,"portfolio + cash"],["RDN Cash",data.summary.totalCash,"all settlement balances"],["Portfolio",data.summary.totalValue,"current market value"],["Unrealized P/L",data.summary.unrealized,`${Number(data.summary.returnPct || 0).toFixed(2)}% return`]].map(([l,v,s]) => <div className={card} key={String(l)}><p className="text-[10px] uppercase tracking-widest text-slate-500">{l}</p><p className="mt-2 text-xl font-bold text-white">{money(v as number)}</p><p className="mt-1 text-[10px] text-slate-600">{s}</p></div>)}</div><section className={card}><div className="mb-4 flex items-center justify-between"><div><h2 className="font-semibold text-white">Investment Accounts</h2><p className="text-xs text-slate-600">Klik account untuk membuka detail account dan RDN.</p></div><button type="button" onClick={() => { openAccountEditor(); setScreen("accounts"); }} className="rounded-lg bg-emerald-400 px-3 py-2 text-xs font-bold text-[#07110b]">+ Account</button></div>{accounts.filter(a => a.isActive !== false).length ? <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{accounts.filter(a => a.isActive !== false).map(a => { const f = feeInfo(a); return <button type="button" key={a.id} onClick={() => chooseAccount(a.id)} className="rounded-2xl border border-white/10 bg-white/[.02] p-5 text-left hover:border-emerald-400/30"><div className="flex items-start justify-between"><div><p className="text-base font-semibold text-white">{a.provider.name}</p><p className="mt-1 text-xs text-slate-500">{f.rdnBankName ? `RDN ${f.rdnBankName}` : "Investment account"} · {a.currency.code}</p></div><span className="text-[10px] font-bold uppercase tracking-widest text-emerald-300">Open →</span></div><div className="mt-5 grid grid-cols-2 gap-3 text-xs"><div><p className="text-slate-600">RDN Cash</p><p className="mt-1 font-semibold text-white">{money(a.cashAccount?.balance ?? 0, a.currency.code)}</p></div><div><p className="text-slate-600">Portfolio</p><p className="mt-1 font-semibold text-white">{money(holdings.filter(h => h.account.id === a.id).reduce((s,h) => s + Number(h.marketValue),0), a.currency.code)}</p></div></div></button>; })}</div> : <div className="rounded-xl border border-dashed border-white/10 p-8 text-center text-xs text-slate-600">Belum ada investment account.</div>}</section></div>}

    {screen === "accounts" && <section className="space-y-5">{editing || !accountId ? <form className={card} onSubmit={saveAccount}><div className="flex items-center justify-between"><div><h2 className="text-lg font-semibold text-white">{editing ? "Edit Investment Account" : "New Investment Account"}</h2><p className="mt-1 text-xs text-slate-500">Broker, website, RDN and trading fees.</p></div>{editing && <button type="button" onClick={() => setEditing(null)} className="text-xs text-slate-500 hover:text-white">Cancel</button>}</div><div className="mt-5 grid gap-3 md:grid-cols-2"><input required className={input} placeholder="Provider e.g. IndoPremier" value={accountForm.providerName} onChange={e => setAccountForm(x => ({ ...x, providerName: e.target.value }))}/><input className={input} placeholder="Website (optional)" value={accountForm.websiteUrl} onChange={e => setAccountForm(x => ({ ...x, websiteUrl: e.target.value }))}/><input className={input} placeholder="RDN bank" value={accountForm.rdnBankName} onChange={e => setAccountForm(x => ({ ...x, rdnBankName: e.target.value }))}/><input className={input} placeholder="RDN account number" value={accountForm.rdnAccountNumber} onChange={e => setAccountForm(x => ({ ...x, rdnAccountNumber: e.target.value }))}/><input required type="number" min="0" step="0.001" className={input} placeholder="Buy fee %" value={accountForm.buyFeePct} onChange={e => setAccountForm(x => ({ ...x, buyFeePct: e.target.value }))}/><input required type="number" min="0" step="0.001" className={input} placeholder="Sell fee %" value={accountForm.sellFeePct} onChange={e => setAccountForm(x => ({ ...x, sellFeePct: e.target.value }))}/><select required className={`${select} md:col-span-2`} value={accountForm.currencyId} onChange={e => setAccountForm(x => ({ ...x, currencyId: e.target.value }))}><option value="">Currency</option>{currencies.map(c => <option key={c.id} value={c.id}>{c.code}</option>)}</select></div><button disabled={busy} className="mt-4 rounded-xl bg-emerald-400 px-5 py-3 text-sm font-bold text-[#07110b]">{editing ? "Update account" : "Save account"}</button></form> : null}
      <section className={card}><div className="flex items-center justify-between"><div><h2 className="font-semibold text-white">Investment Accounts</h2><p className="text-xs text-slate-600">Account menjadi pusat RDN, portfolio dan history.</p></div><button type="button" onClick={() => { openAccountEditor(); }} className="rounded-lg bg-emerald-400 px-3 py-2 text-xs font-bold text-[#07110b]">+ Account</button></div><div className="mt-4 space-y-3">{accounts.map(a => { const f = feeInfo(a); const active = a.isActive !== false; return <div key={a.id} className={`rounded-2xl border ${active ? "border-white/10" : "border-white/5 opacity-60"} bg-white/[.02] p-5`}><div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><button type="button" onClick={() => chooseAccount(a.id)} className="min-w-0 text-left"><div className="flex items-center gap-3"><div className="min-w-0"><p className="text-base font-semibold text-white">{a.provider.name}</p><p className="mt-1 text-xs text-slate-500">{f.rdnBankName ? `RDN ${f.rdnBankName}` : "No RDN details"} · {a.currency.code}</p></div>{!active && <span className="rounded-full border border-white/10 px-2 py-1 text-[9px] uppercase text-slate-500">Closed</span>}</div></button><div className="flex flex-wrap gap-2"><button type="button" onClick={() => { setAccountId(a.id); setCashForm({ cashAccountId: a.cashAccount?.id ?? "", balance: String(a.cashAccount?.balance ?? ""), date: today() }); setHistoryAccountId(a.cashAccount?.id ?? ""); setHistoryOpen(true); }} className="rounded-lg border border-white/10 px-3 py-2 text-xs font-semibold text-slate-300">Update Balance</button><button type="button" onClick={() => openAccountEditor(a)} className="rounded-lg border border-white/10 px-3 py-2 text-xs font-semibold text-slate-300">Edit</button><button type="button" onClick={() => accountAction("account.delete", a)} className="rounded-lg border border-red-400/20 px-3 py-2 text-xs font-semibold text-red-300">Delete</button>{active && <button type="button" onClick={() => accountAction("account.close", a)} className="rounded-lg border border-amber-400/20 px-3 py-2 text-xs font-semibold text-amber-300">Close</button>}</div></div><div className="mt-4 grid gap-3 sm:grid-cols-3"><div className="rounded-xl border border-white/5 px-4 py-3"><p className="text-[10px] uppercase tracking-wider text-slate-600">RDN Cash</p><p className="mt-1 font-semibold text-emerald-300">{money(a.cashAccount?.balance ?? 0, a.currency.code)}</p></div><div className="rounded-xl border border-white/5 px-4 py-3"><p className="text-[10px] uppercase tracking-wider text-slate-600">Buy Fee</p><p className="mt-1 font-semibold text-white">{numberFormat(f.buyFeePct, 3)}%</p></div><div className="rounded-xl border border-white/5 px-4 py-3"><p className="text-[10px] uppercase tracking-wider text-slate-600">Sell Fee</p><p className="mt-1 font-semibold text-white">{numberFormat(f.sellFeePct, 3)}%</p></div></div></div>; })}</div></section>
      {selected && <section className={card}><div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div><p className="text-[10px] uppercase tracking-widest text-emerald-400">{selected.provider.name}</p><h2 className="mt-1 text-2xl font-bold text-white">{feeInfo(selected).rdnBankName ? `RDN ${feeInfo(selected).rdnBankName}` : "Investment Account"}</h2><p className="mt-1 text-xs text-slate-500">{selected.currency.code} · {feeInfo(selected).rdnAccountNumber || "No RDN number"}</p></div><div className="flex flex-wrap gap-2"><button type="button" onClick={() => setScreen("transactions")} className="rounded-xl bg-emerald-400 px-4 py-2.5 text-xs font-bold text-[#07110b]">Open Transactions</button><button type="button" onClick={() => { setScreen("accounts"); setCashForm({ cashAccountId: selected.cashAccount?.id ?? "", balance: String(selected.cashAccount?.balance ?? ""), date: today() }); }} className="rounded-xl border border-white/10 px-4 py-2.5 text-xs font-semibold text-slate-300">Update Balance</button><button type="button" onClick={() => window.location.assign("/transfer")} className="rounded-xl border border-white/10 px-4 py-2.5 text-xs font-semibold text-slate-300">Transfer from Wallet</button></div></div>{selected.cashAccount && <div className="mt-5 grid gap-4 lg:grid-cols-[1fr_1.1fr]"><div className="rounded-2xl border border-emerald-400/15 bg-emerald-400/[.03] p-5"><div className="flex items-start justify-between"><div><p className="text-[10px] uppercase tracking-widest text-slate-500">RDN Balance</p><p className="mt-2 text-2xl font-bold text-white">{money(selected.cashAccount.balance, selected.currency.code)}</p></div><button type="button" onClick={() => { setHistoryAccountId(selected.cashAccount!.id); setHistoryOpen(true); }} className="rounded-lg border border-white/10 px-3 py-2 text-xs font-semibold text-slate-300">View History</button></div><div className="mt-4 flex flex-wrap gap-2"><button type="button" onClick={() => { setCashForm({ cashAccountId: selected.cashAccount!.id, balance: String(selected.cashAccount!.balance), date: today() }); }} className="rounded-lg border border-white/10 px-3 py-2 text-xs font-semibold text-slate-300">Update actual balance</button><label className="cursor-pointer rounded-lg border border-white/10 px-3 py-2 text-xs font-semibold text-slate-300">Import Excel<input type="file" accept=".xlsx,.xls" className="hidden" disabled={importing} onChange={e => { const f = e.target.files?.[0]; if (f) importExcel(f); e.currentTarget.value = ""; }}/></label></div></div>{selected.cashAccount && <WithdrawBox cashAccount={selectedCash ?? { id: selected.cashAccount.id, balance: selected.cashAccount.balance, account: selected } as Cash} cashAccounts={cashAccounts} onWithdraw={withdrawToWallet} busy={busy} />}</div>}{cashForm.cashAccountId === selected.cashAccount?.id && <div className="mt-4 rounded-2xl border border-white/10 bg-[#080f17] p-5"><div className="flex items-end justify-between"><div><p className="text-[10px] uppercase tracking-widest text-slate-500">RDN reconciliation</p><h3 className="mt-1 font-semibold text-white">Update Actual Balance</h3></div><button type="button" onClick={() => setCashForm({ cashAccountId: "", balance: "", date: today() })} className="text-xs text-slate-500">Close</button></div><form className="mt-4 grid gap-3 md:grid-cols-[1fr_1fr_180px_auto]" onSubmit={saveCash}><input required type="number" min="0" step="0.01" className={input} placeholder="Actual balance" value={cashForm.balance} onChange={e => setCashForm(x => ({ ...x, balance: e.target.value }))}/><input required type="date" className={input} value={cashForm.date} onChange={e => setCashForm(x => ({ ...x, date: e.target.value }))}/><div className="rounded-xl border border-white/10 px-3 py-2.5 text-xs text-slate-400">Current<br/><b className="text-white">{money(selected.cashAccount!.balance, selected.currency.code)}</b></div><button disabled={busy} className="rounded-xl bg-emerald-400 px-4 py-2.5 text-sm font-bold text-[#07110b]">Update</button></form></div>}
        <AssetSummaryPanel summaries={assetSummaries} currency={selected.currency.code} onSellAll={asset => { setSellAllAssetId(asset.asset.id); setSellAllPrice(asset.currentPrice != null ? String(asset.currentPrice) : String(asset.minSell || "")); setShowSellAll(true); }} />
        {renderRdnHistory(selected.cashAccount?.id ?? "")}
      </section>}
    </section>}

    {screen === "transactions" && selected && <section className="space-y-5"><div className={card}><div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><div><button type="button" onClick={() => setScreen("overview")} className="mb-2 text-xs text-slate-500">← Investments</button><h2 className="text-2xl font-bold text-white">{selected.provider.name}</h2><p className="mt-1 text-xs text-slate-500">{feeInfo(selected).rdnBankName ? `RDN ${feeInfo(selected).rdnBankName}` : "Investment account"} · {selected.currency.code} · Buy {numberFormat(fee.buyFeePct,3)}% · Sell {numberFormat(fee.sellFeePct,3)}%</p></div><div className="flex flex-wrap gap-2"><label className="cursor-pointer rounded-xl border border-white/10 px-4 py-2.5 text-xs font-bold text-slate-300">{importing ? "Importing…" : "Import Excel"}<input type="file" accept=".xlsx,.xls" className="hidden" disabled={importing} onChange={e => { const f = e.target.files?.[0]; if (f) importExcel(f); e.currentTarget.value = ""; }}/></label><button type="button" onClick={() => openTrade("BUY")} className="rounded-xl bg-emerald-400 px-4 py-2.5 text-xs font-bold text-[#07110b]">+ Transaction</button></div></div></div>
      <AssetSummaryPanel summaries={assetSummaries} currency={selected.currency.code} compact onSellAll={asset => { setSellAllAssetId(asset.asset.id); setSellAllPrice(asset.currentPrice != null ? String(asset.currentPrice) : String(asset.minSell || "")); setShowSellAll(true); }} />
      <section className={card}><div className="mb-4 flex items-center justify-between"><div><h3 className="font-semibold text-white">Open Positions</h3><p className="text-xs text-slate-600">Posisi yang masih memiliki remaining selalu ditampilkan paling atas.</p></div><div className="text-right text-xs text-slate-500">Open lots <b className="text-white">{ledger?.summary.openLots ?? 0}</b></div></div><div className="overflow-x-auto"><table className="w-full min-w-[1220px] table-fixed text-left text-xs"><thead className="border-b border-white/5 text-[10px] uppercase tracking-wider text-slate-600"><tr><th className="w-[9%] px-2 py-3">Date</th><th className="w-[8%]">Asset</th><th className="w-[9%]">Buy</th><th className="w-[13%]">Cost</th><th className="w-[10%]">Remaining</th><th className="w-[10%]">Current</th><th className="w-[11%]">Min. Sell</th><th className="w-[11%]">P/L</th><th className="w-[19%] text-right pr-2">Action</th></tr></thead><tbody className="divide-y divide-white/5">{openRows.map(row => <tr key={row.id}><td className="px-2 py-3 text-slate-400">{new Date(row.transactionDate).toLocaleDateString("id-ID")}</td><td><b className="block text-white">{row.asset.symbol || row.asset.name}</b><span className="block max-w-[90px] truncate text-[10px] text-slate-600">{row.asset.name}</span></td><td>{money(row.unitPrice,row.asset.currency.code)}</td><td>{money(Number(row.totalCost) * (Number(row.remainingQuantity) / Math.max(Number(row.quantity),1)),row.asset.currency.code)}</td><td>{numberFormat(Number(row.remainingQuantity) / stockUnits(row.asset), row.asset.assetType === "STOCK" ? 0 : 2)}</td><td>{row.currentPrice != null ? money(row.currentPrice,row.asset.currency.code) : "—"}</td><td className="text-amber-300">{money(row.minimumSellPrice,row.asset.currency.code)}</td><td className={Number(row.unrealizedGainLoss) >= 0 ? "text-emerald-300" : "text-red-300"}>{money(row.unrealizedGainLoss,row.asset.currency.code)}</td><td className="text-right pr-2"><div className="flex items-center justify-end gap-2"><button type="button" onClick={() => openTrade("SELL", row)} className="rounded-lg bg-emerald-400 px-3 py-1.5 font-bold text-[#07110b]">Sell / Split</button><button type="button" disabled={busy} onClick={() => { if (window.confirm("Hapus transaksi pembelian ini? Hanya lot yang belum pernah terjual yang bisa dihapus.")) run({ action: "transaction.delete", transactionId: row.id }, "Transaction deleted."); }} className="rounded-lg border border-red-400/20 px-3 py-1.5 font-bold text-red-300">Delete</button></div></td></tr>)}</tbody></table>{!openRows.length && <div className="p-10 text-center text-xs text-slate-600">Tidak ada posisi terbuka.</div>}</div></section>
      <section className={card}><div className="mb-4"><h3 className="font-semibold text-white">Closed Transactions</h3><p className="text-xs text-slate-600">Histori penjualan tetap ditampilkan setelah lot habis terjual.</p></div><div className="overflow-x-auto"><table className="w-full min-w-[980px] table-fixed text-left text-xs"><thead className="border-b border-white/5 text-[10px] uppercase tracking-wider text-slate-600"><tr><th className="w-[10%] px-2 py-3">Date</th><th className="w-[10%]">Asset</th><th className="w-[12%]">Buy</th><th className="w-[12%]">Sell</th><th className="w-[12%]">Cost</th><th className="w-[12%]">Sold</th><th className="w-[14%]">Net Proceeds</th><th className="w-[14%]">Realized P/L</th><th className="w-[8%]">Status</th></tr></thead><tbody className="divide-y divide-white/5">{closedSales.map(({ lot, sale }) => <tr key={`${lot.id}-${sale.id}`}><td className="px-2 py-3 text-slate-400">{new Date(sale.date).toLocaleDateString("id-ID")}</td><td><b className="text-white">{lot.asset.symbol || lot.asset.name}</b></td><td>{money(lot.unitPrice,lot.asset.currency.code)}</td><td>{money(sale.price,lot.asset.currency.code)}</td><td>{money(Number(lot.totalCost) * (Number(sale.quantity) / Math.max(Number(lot.quantity),1)),lot.asset.currency.code)}</td><td>{numberFormat(Number(sale.quantity) / stockUnits(lot.asset),lot.asset.assetType === "STOCK" ? 0 : 2)} lot</td><td>{money(sale.proceeds,lot.asset.currency.code)}</td><td className={Number(sale.realized) >= 0 ? "text-emerald-300" : "text-red-300"}>{money(sale.realized,lot.asset.currency.code)}</td><td className="font-semibold text-slate-500">SOLD</td></tr>)}</tbody></table>{!closedSales.length && <div className="p-10 text-center text-xs text-slate-600">Belum ada histori penjualan.</div>}</div></section></section>}

    {!selected && screen === "transactions" && <section className={card}><p className="text-sm text-slate-500">Pilih investment account terlebih dahulu dari Accounts.</p></section>}

    {showTrade && selected && <div className="fixed inset-0 z-[90] flex items-center justify-center bg-black/70 p-4"><form onSubmit={submitTrade} className="w-full max-w-2xl rounded-2xl border border-white/10 bg-[#0d151e] p-6 shadow-2xl"><div className="flex items-center justify-between"><div><p className="text-[10px] uppercase tracking-widest text-emerald-400">{selected.provider.name}</p><h2 className="mt-1 text-2xl font-bold text-white">{trade.type === "BUY" ? "New Buy Transaction" : "Sell / Split Transaction"}</h2></div><button type="button" onClick={() => setShowTrade(false)} className="text-slate-500 hover:text-white">✕</button></div><div className="mt-5 flex rounded-xl border border-white/10 p-1">{(["BUY","SELL"] as const).map(t => <button key={t} type="button" onClick={() => setTrade(x => ({ ...x, type: t, assetId: "", assetQuery: "", sourceLotId: "" }))} className={`flex-1 rounded-lg px-4 py-2.5 text-sm font-bold ${trade.type === t ? "bg-emerald-400 text-[#07110b]" : "text-slate-500"}`}>{t}</button>)}</div><div className="mt-4 grid gap-3 md:grid-cols-2"><AssetPicker assets={trade.type === "SELL" ? assetSummaries.map(s => s.asset) : pickerAssets} value={trade.assetQuery} selectedId={trade.assetId} onQueryChange={v => setTrade(x => ({ ...x, assetQuery: v, assetId: "", sourceLotId: "" }))} onSelect={chooseAsset}/><input required type="date" className={input} value={trade.date} onChange={e => setTrade(x => ({ ...x, date: e.target.value }))}/></div>{trade.type === "SELL" && <select required className={`mt-3 ${select}`} value={trade.sourceLotId} onChange={e => { const row = ledger?.rows.find(r => r.lotId === e.target.value); setTrade(x => ({ ...x, sourceLotId: e.target.value, unitPrice: row?.currentPrice ? String(row.currentPrice) : String(row?.minimumSellPrice ?? "") })); }}>{<option value="">Select purchase lot to sell</option>}{ledger?.rows.filter(r => Number(r.remainingQuantity) > 0 && r.asset.id === trade.assetId).map(r => <option key={r.lotId} value={r.lotId}>{new Date(r.transactionDate).toLocaleDateString("id-ID")} · {r.asset.symbol || r.asset.name} · remaining {numberFormat(Number(r.remainingQuantity) / stockUnits(r.asset), r.asset.assetType === "STOCK" ? 0 : 2)}</option>)}</select>}
      <div className="mt-3 grid gap-3 md:grid-cols-3"><input required min="0.000001" step="any" type="number" className={`${input} ${trade.type === "SELL" && !sellValid ? "border-red-400/60" : ""}`} placeholder={selectedAsset?.assetType === "STOCK" ? "Quantity (lot)" : "Quantity"} value={trade.quantity} max={sellLot ? String(Number(sellLot.remainingQuantity) / stockUnits(sellLot.asset)) : undefined} onChange={e => setTrade(x => ({ ...x, quantity: e.target.value }))}/><input required min="0.000001" step="any" type="number" className={input} placeholder="Unit price" value={trade.unitPrice} onChange={e => setTrade(x => ({ ...x, unitPrice: e.target.value }))}/><div className="rounded-xl border border-white/10 bg-white/[.02] px-3 py-2.5 text-xs text-slate-400"><span>{trade.type === "BUY" ? "Cash required" : "Net proceeds"}</span><strong className="mt-1 block text-white">{money((Number(trade.quantity || 0) * stockUnits(selectedAsset) * Number(trade.unitPrice || 0)) * (trade.type === "BUY" ? (1 + fee.buyFeePct/100) : (1 - fee.sellFeePct/100)), selected.currency.code)}</strong></div></div>{trade.type === "SELL" && <div className={`mt-3 grid gap-3 md:grid-cols-2 rounded-xl border p-4 ${sellValid ? "border-emerald-400/20 bg-emerald-400/[.03]" : "border-red-400/20 bg-red-400/[.03]"}`}><div><p className="text-[10px] uppercase tracking-wider text-slate-500">Estimated P/L after sell fee</p><p className={`mt-1 text-xl font-bold ${sellLot && Number(trade.quantity) * stockUnits(selectedAsset) * Number(trade.unitPrice || 0) * (1 - fee.sellFeePct/100) - (sellLot ? Number(sellLot.totalCost) * ((Number(trade.quantity) * stockUnits(selectedAsset)) / Math.max(Number(sellLot.quantity),1)) : 0) >= 0 ? "text-emerald-300" : "text-red-300"}`}>{sellLot && trade.quantity && trade.unitPrice ? money((sellNetProceeds(trade, selectedAsset, sellLot, fee.sellFeePct)),selected.currency.code) : "—"}</p></div><div><p className="text-[10px] uppercase tracking-wider text-slate-500">Remaining after sale</p><p className="mt-1 text-xl font-bold text-white">{sellLot ? numberFormat(Math.max(0,(Number(sellLot.remainingQuantity) - Number(trade.quantity || 0) * stockUnits(selectedAsset))) / stockUnits(sellLot.asset), sellLot.asset.assetType === "STOCK" ? 0 : 2) : "—"}</p>{!sellValid && <p className="mt-1 text-xs text-red-300">Quantity melebihi remaining lot.</p>}</div></div>}
      <div className="mt-3 rounded-xl border border-emerald-400/15 bg-emerald-400/[.03] px-4 py-3"><p className="text-[10px] uppercase tracking-wider text-slate-500">Auto fee · {numberFormat(trade.type === "BUY" ? fee.buyFeePct : fee.sellFeePct,3)}%</p><p className="mt-1 font-bold text-emerald-300">{money((Number(trade.quantity || 0) * stockUnits(selectedAsset) * Number(trade.unitPrice || 0)) * (trade.type === "BUY" ? fee.buyFeePct : fee.sellFeePct) / 100,selected.currency.code)}</p></div><select required className={`mt-3 ${select}`} value={trade.fundingCashAccountId} onChange={e => setTrade(x => ({ ...x, fundingCashAccountId: e.target.value }))}><option value="">Select RDN / settlement</option>{compatibleCash.map(c => <option key={c.id} value={c.id}>{c.account.name} · {money(c.balance,c.account.currency.code)}</option>)}</select><details className="mt-3 rounded-xl border border-white/5 p-3"><summary className="cursor-pointer text-xs font-semibold text-slate-400">Tax / Other</summary><div className="mt-3 grid gap-3 md:grid-cols-2"><input type="number" min="0" step="any" className={input} placeholder="Tax" value={trade.tax} onChange={e => setTrade(x => ({ ...x, tax: e.target.value }))}/><input type="number" min="0" step="any" className={input} placeholder="Other charges" value={trade.other} onChange={e => setTrade(x => ({ ...x, other: e.target.value }))}/></div></details><div className="mt-5 flex justify-end gap-2"><button type="button" onClick={() => setShowTrade(false)} className="rounded-xl border border-white/10 px-4 py-2.5 text-sm text-slate-300">Cancel</button><button type="submit" disabled={busy || !selectedAsset || !trade.quantity || !trade.unitPrice || !trade.fundingCashAccountId || !sellValid || (trade.type === "SELL" && !trade.sourceLotId)} className="rounded-xl bg-emerald-400 px-5 py-2.5 text-sm font-bold text-[#07110b] disabled:cursor-not-allowed disabled:opacity-40">{busy ? "Saving…" : "Save transaction"}</button></div></form></div>}

    {showSellAll && selected && sellAllAsset && <div className="fixed inset-0 z-[95] flex items-center justify-center bg-black/75 p-4"><div className="w-full max-w-3xl rounded-2xl border border-white/10 bg-[#0d151e] p-6 shadow-2xl"><div className="flex items-center justify-between"><div><p className="text-[10px] uppercase tracking-widest text-emerald-400">SELL ALL</p><h2 className="mt-1 text-2xl font-bold text-white">{sellAllAsset.asset.symbol || sellAllAsset.asset.name}</h2><p className="mt-1 text-xs text-slate-500">{numberFormat(sellAllAsset.quantity / stockUnits(sellAllAsset.asset), sellAllAsset.asset.assetType === "STOCK" ? 0 : 2)} lot available · {fee.sellFeePct.toFixed(3)}% sell fee</p></div><button type="button" onClick={() => setShowSellAll(false)} className="text-slate-500 hover:text-white">✕</button></div><div className="mt-5 grid gap-3 md:grid-cols-3"><button type="button" onClick={() => setSellAllPrice(String(sellAllAsset.currentPrice ?? ""))} className="rounded-xl border border-white/10 p-3 text-left hover:border-emerald-400/30"><p className="text-[10px] uppercase text-slate-500">Current</p><p className="mt-1 font-semibold text-white">{sellAllAsset.currentPrice != null ? money(sellAllAsset.currentPrice,selected.currency.code) : "—"}</p></button><button type="button" onClick={() => setSellAllPrice(String(sellAllAsset.minSell))} className="rounded-xl border border-white/10 p-3 text-left hover:border-emerald-400/30"><p className="text-[10px] uppercase text-slate-500">Break-even</p><p className="mt-1 font-semibold text-amber-300">{money(sellAllAsset.minSell,selected.currency.code)}</p></button><div className="rounded-xl border border-white/10 p-3"><label className="text-[10px] uppercase text-slate-500">Custom sell price</label><input type="number" min="0.01" step="0.01" className="mt-1 w-full bg-transparent text-lg font-bold text-white outline-none" value={sellAllPrice} onChange={e => setSellAllPrice(e.target.value)} /></div></div>{sellAllPreview && <><div className="mt-5 grid gap-3 md:grid-cols-4"><div className="rounded-xl border border-white/5 p-3"><p className="text-[10px] text-slate-500">Gross</p><p className="mt-1 font-semibold text-white">{money(sellAllPreview.totalGross,selected.currency.code)}</p></div><div className="rounded-xl border border-white/5 p-3"><p className="text-[10px] text-slate-500">Sell fee</p><p className="mt-1 font-semibold text-white">{money(sellAllPreview.totalFee,selected.currency.code)}</p></div><div className="rounded-xl border border-white/5 p-3"><p className="text-[10px] text-slate-500">Net proceeds</p><p className="mt-1 font-semibold text-white">{money(sellAllPreview.totalNet,selected.currency.code)}</p></div><div className={`rounded-xl border p-3 ${sellAllPreview.pnl >= 0 ? "border-emerald-400/20 bg-emerald-400/[.03]" : "border-red-400/20 bg-red-400/[.03]"}`}><p className="text-[10px] text-slate-500">Estimated P/L</p><p className={`mt-1 font-semibold ${sellAllPreview.pnl >= 0 ? "text-emerald-300" : "text-red-300"}`}>{sellAllPreview.pnl >= 0 ? "+" : ""}{money(sellAllPreview.pnl,selected.currency.code)}</p></div></div><div className="mt-5 overflow-hidden rounded-xl border border-white/5"><div className="grid grid-cols-[1.2fr_.8fr_.8fr_.9fr_.9fr] gap-2 border-b border-white/5 bg-white/[.02] px-4 py-3 text-[10px] uppercase tracking-wider text-slate-600"><span>Lot</span><span>Remaining</span><span>Gross</span><span>Cost</span><span>P/L</span></div>{sellAllPreview.rows.map(({ row, qty, gross, cost, pnl }) => <div key={row.lotId} className="grid grid-cols-[1.2fr_.8fr_.8fr_.9fr_.9fr] gap-2 border-b border-white/5 px-4 py-3 text-xs last:border-0"><span><b className="text-white">{new Date(row.transactionDate).toLocaleDateString("id-ID")} · {row.asset.symbol || row.asset.name}</b><span className="block text-[10px] text-slate-600">Buy {money(row.unitPrice,row.asset.currency.code)}</span></span><span className="text-slate-300">{numberFormat(qty / stockUnits(row.asset), row.asset.assetType === "STOCK" ? 0 : 2)} lot</span><span className="text-slate-300">{money(gross,selected.currency.code)}</span><span className="text-slate-300">{money(cost,selected.currency.code)}</span><span className={pnl >= 0 ? "text-emerald-300" : "text-red-300"}>{pnl >= 0 ? "+" : ""}{money(pnl,selected.currency.code)}</span></div>)}</div></>}
        <div className="mt-5 flex justify-end gap-2"><button type="button" onClick={() => setShowSellAll(false)} className="rounded-xl border border-white/10 px-4 py-2.5 text-sm text-slate-300">Cancel</button><button type="button" disabled={busy || !sellAllPrice || !sellAllPreview || !selected.cashAccount?.id} onClick={sellAll} className="rounded-xl bg-emerald-400 px-5 py-2.5 text-sm font-bold text-[#07110b] disabled:cursor-not-allowed disabled:opacity-40">{busy ? "Selling…" : "Confirm Sell All"}</button></div></div></div>}
  </div>;
}

function sellNetProceeds(trade: Trade, asset: Asset | undefined, lot: LotRow, sellFeePct: number) {
  const units = stockUnits(asset);
  const sellUnits = Number(trade.quantity || 0) * units;
  const gross = sellUnits * Number(trade.unitPrice || 0);
  const net = gross * (1 - sellFeePct / 100) - Number(trade.tax || 0) - Number(trade.other || 0);
  const cost = Number(lot.totalCost) * (sellUnits / Math.max(Number(lot.quantity), 1));
  return net - cost;
}

function AssetSummaryPanel({ summaries, currency, onSellAll, compact = false }: { summaries: AssetSummary[]; currency: string; onSellAll: (asset: AssetSummary) => void; compact?: boolean }) {
  if (!summaries.length) return <section className={card}><h3 className="font-semibold text-white">Asset Summary</h3><div className="mt-4 rounded-xl border border-dashed border-white/10 p-7 text-center text-xs text-slate-600">Belum ada asset yang masih dimiliki.</div></section>;
  return <section className={card}><div className="mb-4 flex items-center justify-between"><div><h3 className="font-semibold text-white">Asset Summary</h3><p className="text-xs text-slate-600">Gabungan seluruh lot yang masih dimiliki pada account ini.</p></div><span className="text-[10px] uppercase tracking-wider text-slate-600">{summaries.length} assets</span></div><div className="overflow-x-auto"><table className={`w-full text-left text-xs ${compact ? "min-w-[980px]" : "min-w-[1020px]"}`}><thead className="border-b border-white/5 text-[10px] uppercase tracking-wider text-slate-600"><tr><th className="px-2 py-3">Asset</th><th>Total</th><th>Avg. Cost</th><th>Current</th><th>Market Value</th><th>Net Sell Value</th><th>P/L</th><th>Min. Sell</th><th className="text-right pr-2">Action</th></tr></thead><tbody className="divide-y divide-white/5">{summaries.map(s => <tr key={s.asset.id}><td className="px-2 py-3"><b className="text-white">{s.asset.symbol || s.asset.name}</b><span className="block text-[10px] text-slate-600">{s.asset.name}</span></td><td>{numberFormat(s.quantity / stockUnits(s.asset),s.asset.assetType === "STOCK" ? 0 : 2)} lot</td><td>{money(s.avgCost,currency)}</td><td>{s.currentPrice == null ? "—" : money(s.currentPrice,currency)}</td><td>{money(s.marketValue,currency)}</td><td>{money(s.netValue,currency)}</td><td className={s.pnl >= 0 ? "text-emerald-300" : "text-red-300"}>{s.pnl >= 0 ? "+" : ""}{money(s.pnl,currency)}</td><td className="text-amber-300">{money(s.minSell,currency)}</td><td className="text-right pr-2"><button type="button" onClick={() => onSellAll(s)} className="rounded-lg bg-emerald-400 px-3 py-1.5 font-bold text-[#07110b]">Sell All</button></td></tr>)}</tbody></table></div></section>;
}

function WithdrawBox({ cashAccount, cashAccounts, onWithdraw, busy }: { cashAccount: Cash; cashAccounts: Cash[]; onWithdraw: (cashAccountId: string, amount: string, walletId: string) => void; busy: boolean }) {
  const [wallets, setWallets] = useState<Array<{ id: string; name: string; balance: string | number; currency: { code: string } }>>([]);
  const [walletId, setWalletId] = useState("");
  const [amount, setAmount] = useState("");
  useEffect(() => { fetch("/api/investments/cash-transfer", { cache: "no-store" }).then(async r => r.json()).then(j => { setWallets(j.wallets ?? []); }); }, []);
  const compatible = wallets.filter(w => w.currency.code === cashAccount.account.currency.code);
  useEffect(() => { if (!compatible.some(w => w.id === walletId)) setWalletId(compatible[0]?.id ?? ""); }, [compatible, walletId]);
  const valid = !!walletId && Number(amount) > 0 && Number(amount) <= Number(cashAccount.balance);
  return <div className="rounded-2xl border border-white/10 bg-[#080f17] p-5"><div className="flex items-center justify-between"><div><p className="text-[10px] uppercase tracking-widest text-emerald-400">RDN → Wallet</p><h3 className="mt-1 font-semibold text-white">Withdraw</h3></div><span className="text-xs text-emerald-300">Available {money(cashAccount.balance,cashAccount.account.currency.code)}</span></div><div className="mt-4 space-y-3"><select className={select} value={walletId} onChange={e => setWalletId(e.target.value)}><option value="">Select wallet</option>{compatible.map(w => <option key={w.id} value={w.id}>{w.name} · {money(w.balance,w.currency.code)}</option>)}</select><input type="number" min="0.01" step="0.01" max={String(cashAccount.balance)} className={input} placeholder="Amount" value={amount} onChange={e => setAmount(e.target.value)}/><button type="button" disabled={busy || !valid} onClick={() => onWithdraw(cashAccount.id, amount, walletId)} className="w-full rounded-xl bg-emerald-400 px-4 py-3 text-sm font-bold text-[#07110b] disabled:cursor-not-allowed disabled:opacity-40">{busy ? "Processing…" : "Withdraw to Wallet"}</button></div></div>;
}
